// Keyboard scan codes as message::codeX carries them (low byte for
// plain keys, the second byte for extended keys - textntry's numpad
// row and smackmgr's video-abort filter read them). NH3API
// interface/key_codes.hpp EKeyCodes spellings; only the byte-proven
// consumers' values are listed - grow the roster as consumers land.
enum EKeyCodes {
    // The three keys textEntryWidget::IgnoreKey (0x5bba20) swallows
    // before its OnKeyPress ever sees them; its dec/sub/sub switch
    // descent fixes the values 1, 15 and 28 exactly.
    KEYCODE_ESCAPE = 0x01,
    KEYCODE_TAB = 0x0f,
    KEYCODE_ENTER = 0x1c,
    KEYCODE_A = 0x1e,
    KEYCODE_C = 0x2e,
    // The nine letter/space rows advManager::ProcessKeyPress's byte-index
    // table names. Each value is read straight off that table (the index
    // is codeX - 1) and the arm behind it confirms the letter: T next
    // town, I scenario info, P puzzle map, S save, D dig, L load, V view
    // world, N new game, SPACE trigger the cell under the hero.
    KEYCODE_T = 0x14,
    KEYCODE_I = 0x17,
    KEYCODE_P = 0x19,
    KEYCODE_S = 0x1f,
    KEYCODE_D = 0x20,
    // ProcessCombatMsg's Complete-only Faerie Dragon spell shortcut.
    // The retail key jump table fixes the standard set-1 F scan code.
    KEYCODE_F = 0x21,
    KEYCODE_L = 0x26,
    KEYCODE_V = 0x2f,
    KEYCODE_N = 0x31,
    KEYCODE_SPACE = 0x39,
    // The function-key band AsciiConvert singles out: F1..F10 are the
    // contiguous 0x3b..0x44 run, F11/F12 sit apart at 0x57/0x58 - all
    // four bounds byte-proven by its scan-table branch.
    KEYCODE_F1 = 0x3b,
    KEYCODE_F2 = 0x3c,
    KEYCODE_F3 = 0x3d,
    KEYCODE_F4 = 0x3e,
    KEYCODE_F5 = 0x3f,
    KEYCODE_F6 = 0x40,
    KEYCODE_F7 = 0x41,
    KEYCODE_F8 = 0x42,
    KEYCODE_F10 = 0x44,
    KEYCODE_KP_7 = 0x47,
    KEYCODE_KP_8 = 0x48,
    KEYCODE_KP_9 = 0x49,
    // Combat-log scroll-up. The adjacent numpad table fixes the value.
    KEYCODE_KP_MINUS = 0x4a,
    KEYCODE_KP_4 = 0x4b,
    KEYCODE_KP_5 = 0x4c,
    KEYCODE_KP_6 = 0x4d,
    KEYCODE_KP_1 = 0x4f,
    KEYCODE_KP_2 = 0x50,
    KEYCODE_KP_3 = 0x51,
    KEYCODE_KP_0 = 0x52,
    // The filename-charset rows CSaveGameEdit::IgnoreKey (0x57cfe0)
    // dispatches: its 0x53-entry byte-index table files exactly these
    // scan codes into its reject / shift-reject arms, fixing each
    // value. They are the standard set-1 codes for the digit and
    // punctuation keys whose (shifted) characters are illegal in DOS
    // filenames.
    KEYCODE_2 = 0x03,
    KEYCODE_5 = 0x06,
    KEYCODE_8 = 0x09,
    KEYCODE_SEMICOLON = 0x27,
    KEYCODE_APOSTROPHE = 0x28,
    KEYCODE_GRAVE = 0x29,
    KEYCODE_BACKSLASH = 0x2b,
    KEYCODE_COMMA = 0x33,
    KEYCODE_PERIOD = 0x34,
    KEYCODE_SLASH = 0x35,
    // The numpad Del/decimal key, one past KP_0 - the caret editor's
    // forward-delete arm. Its value is forced by the same dense jump
    // table that fixes KP_1/KP_4/KP_6/KP_7: textEntryWidget::OnKeyPress
    // 0x5bac50 indexes msg->codeX over 0x47..0x53 and files this case
    // at the table's last slot.
    KEYCODE_KP_DECIMAL = 0x53,
    // Not a scan code: the value inputManager::AsciiConvert 0x4ec6f0
    // leaves in msg->codeX for the backspace key, which is the only
    // reason a consumer ever sees it. textEntryWidget::OnKeyPress tests
    // for it immediately after the AsciiConvert call and takes its
    // delete-left arm. Filed in this enum because codeX is the carrier
    // for both domains and every other consumer of the ASCII half
    // compares character literals.
    KEYCODE_ASCII_BACKSPACE = 0x7f,
    KEYCODE_F11 = 0x57,
    KEYCODE_F12 = 0x58
};

// Dreamcast roster with the 40->32-byte message shift: iBuffer@0x38
// (64 messages), iHead@0x838, iTail@0x83c, bufferBusy@0x840,
// mouseInstalled@0x844, scanCodeTable@0x848, keyboardInstalled@0x948,
// keyboardFilter@0x94c, keyCodeType@0x950, extendFlag@0x954,
// currWidgetID@0x958, prevDialog@0x95c (tail past that unmodeled).
// GetEvent returns the message BY VALUE (retail body 0x4ec590).
class inputBufferMessage : public message {
public:
    inputBufferMessage()
    {
        id = 0;
        codeX = 0;
        codeY = 0;
        qualifier = 0;
        mouseX = 0;
        mouseY = 0;
        extra = 0;
        window = 0;
    }
};
SIZE(inputBufferMessage, 32);

class inputManager : public baseManager {
public:
    inputBufferMessage iBuffer[64];
    int iHead;
    int iTail;
    int bufferBusy;
    int mouseInstalled;
    // 128 SHORTS, not 256 bytes: AsciiConvert indexes it
    // `[ecx + 2*codeX + 0x848]` and reads the function-key band with
    // `movsx ...word ptr`, everything else with the low byte only.
    // The 0x848..0x947 span is unchanged.
    short scanCodeTable[128];
    int keyboardInstalled;
    int keyboardFilter;
    int keyCodeType;
    int extendFlag;
    int currWidgetID;
    int prevDialog;

    inputManager();
    message GetEvent();
    // Retail 0x4ec640, GetEvent's twin one row over: same queue head,
    // same AsciiConvert hook, but it normalises iHead instead of
    // advancing it (`and eax,0x8000003f` on the UN-incremented index).
    message PeekEvent();
    void Flush();
    void ForceMouseMove();
    void AsciiConvert(message* msg);
    void MakeScanCodeTable();

    // Located 2026-08-06 by homm3.analysis.dc_bracket (link-order
    // bracket, gap of 3 between the ctor and Flush) and verified by
    // body: Open clears the 0x200-dword buffer and latches its
    // argument into keyboardFilter; Close undoes it under status==1;
    // Main is the trivial `return 0`.
    // CORRECTION 2026-08-08: the trailing _vslot3/_vslot4/_vslot5 that
    // used to sit here were basemgr.h's fabricated slots 3-5 (see the
    // correction note there - baseManager's table is three wide), and
    // Main took `message*`, which did NOT override baseManager's
    // `message&` slot and so appended a seventh entry. DC spells it
    // ?Main@inputManager@@UAAHAAUmessage@@@Z - a reference - and
    // inputManager's retail table is three slots, exactly these.
    virtual int Open(int kFilter);        // slot 0, 0x4ec4d0
    virtual void Close();                 // slot 1, 0x4ec540
    virtual int Main(message& msg);       // slot 2, 0x4ec560
};

